static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) (timeBucket % 10000 / 100);
    int day = (int) (timeBucket % 100);

    if (dayStep == 1) {
        return timeBucket;
    } else if (dayStep == 2) {
        if (day % 2 == 0) {
            return (year * 10000) + (month * 100) + (day - 1);
        } else {
            return (year * 10000) + (month * 100) + (day + 1);
        }
    } else {
        int mod = (day - 1) % dayStep;
        if (mod == 0) {
            return (year * 10000) + (month * 100) + (day + (dayStep - 1));
        } else {
            return (year * 10000) + (month * 100) + (day - mod);
        }
    }
}

