public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = Math.min(index + len, str.length());
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if ((c & 0xFF80) == 0) {
            size++; // 1-byte characters
        } else if ((c & 0xF800) == 0) {
            size += 2; // 2-byte characters
        } else if ((c & 0xFC00) == 0) {
            size += 3; // 3-byte characters
        } else {
