    box1.setMinX(centerX - halfWidth);
    box1.setMaxX(centerX);
    box1.setMinY(box.getMinY());
    box1.setMaxY(box.getMaxY());

    Box2D box2 = new Box2D();
    box2.setMinX(centerX);
    box2.setMaxX(centerX + halfWidth);
    box2.setMinY(box.getMinY());
    box2.setMaxY(box.getMaxY());

    return new Pair<>(box1, box2);
}

