    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder result = new StringBuilder();
    boolean escapeNextChar = false;
    for (char ch : input.toCharArray()) {
        if (escapeNextChar) {
            result.append(ch);
            escapeNextChar = false;
        } else if (ch == '\\') {
            escapeNextChar = true;
        } else {
            result.append(ch);
        }
    }
    return result.toString();
}

