        if (c == '\\' && i + 1 < input.length()) {
            char nextChar = input.charAt(i + 1);
            if (nextChar == '\\' || nextChar == '.') {
                result.append(nextChar);
                i++; // Skip the next character
            } else {
                result.append(c);
