private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (E edge : graph.edgeSet()) {
        Set<Integer> vertexSet = new HashSet<>(graph.vertexSet());
        vertexSet.remove(edge.getSource());
        vertexSet.remove(edge.getTarget());

        for (Integer vertex : vertexSet) {
            List<Pair<Integer,Integer>> minimalSeparator = findMinimalSeparator(graph, vertex);

            if (!minimalSeparator.isEmpty()) {
                globalSeparatorList.add(new Pair<>(minimalSeparator, edge));
            }
        }
    }

    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> findMinimalSeparator(Graph<Integer,E> graph, Integer vertex) {
    List<Pair<Integer,Integer>> minimalSeparator = new ArrayList<>();

    for (Integer neighbor : graph.neighborListOf(vertex)) {
        if (graph.hasEdgeBetween(vertex, neighbor)) {
            continue;
        }

        for (Integer otherNeighbor : graph.neighborListOf(neighbor)) {
            if (otherNeighbor == vertex) {
                continue;
            }

            if (!graph.hasEdgeBetween(vertex, otherNeighbor)) {
                minimalSeparator.add(new Pair<>(vertex, otherNeighbor));
            }
        }
    }

    return minimalSeparator;
}

