private static boolean isWithinTimeRange(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\t");
            if (parts.length >= 3) {
                long startTime = Long.parseLong(parts[1]);
                long endTime = Long.parseLong(parts[2]);
                ProfileAnalyzeTimeRange range = new ProfileAnalyzeTimeRange(startTime, endTime);
                if (timeRanges.contains(range)) {
                    ThreadSnapshot snapshot = new ThreadSnapshot(parts[0], startTime, endTime);
                    snapshots.add(snapshot);
                }
            }
        }
    }
    return snapshots;
}

